        }
      ]
    },
    {
      "id": "thetaSweep",
      "type": "slider",
      "teaches": "Sweeping θ from 0 to π/2 shows that R is swept out by radial strips whose length 2(1+cos θ) − 2 shrinks to zero as θ reaches π/2.",
      "label": "θ (radial strip angle)",
