      "label": "View",
      "options": [
        "Single strip",
        "Swept region",
        "Full region R"
      ],
      "default": "Full region R"
    }
  ],
  "demo_steps": [
    {
      "title": "The two boundary curves",
      "narration": "The blue circle r = 2 and the purple cardioid r = 2(1 + cos θ) both pass through (0, 2) and the cardioid reaches out to r = 4 at θ = 0. In the first quadrant the cardioid lies outside the circle.",
      "state": {
        "viewMode": "Full region R",
        "thetaSweep": 0
      }
    },
    {
      "title": "One radial strip",
