      "state": {
        "viewMode": "Single strip",
        "thetaSweep": 1.5
      }
    },
    {
      "title": "Sweeping θ builds the region",
      "narration": "Sweep θ from 0 to π/2 and the strips accumulate into the shaded region R — the geometric meaning of the outer θ-limits.",
