// @FIGURE_CODE_BEGIN
(function () {
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');

  var COL = {
    axis: '#111111',
    circle: '#3fa8e0',
    outer: '#b055be',
    fill: '#cbe5f2',
    strip: '#8fc9e8',
    ray: '#ee3a33'
  };

  // base world box (pole at origin); one dimension always matches exactly
  var LEFT = -4.1, RIGHT = 4.8, BOT = -3.2, TOP = 3.5;
  var BASE_W = RIGHT - LEFT, BASE_H = TOP - BOT;
  var CX = (LEFT + RIGHT) / 2, CY = (BOT + TOP) / 2;
  var dom = { x0: LEFT, x1: RIGHT, y0: BOT, y1: TOP };

  var containerEl = document.getElementById('container');
  function innerSize() {
