<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');

  var COL = {
    axis: '#111111',
    circle: '#3fa8e0',
    outer: '#b055be',
    fill: '#cbe5f2',
    strip: '#8fc9e8',
    ray: '#ee3a33'
  };

  // base world box (pole at origin); one dimension always matches exactly
  var LEFT = -4.1, RIGHT = 4.8, BOT = -3.2, TOP = 3.5;
  var BASE_W = RIGHT - LEFT, BASE_H = TOP - BOT;
  var CX = (LEFT + RIGHT) / 2, CY = (BOT + TOP) / 2;
  var dom = { x0: LEFT, x1: RIGHT, y0: BOT, y1: TOP };

  var containerEl = document.getElementById('container');
  function innerSize() {
    var st = getComputedStyle(containerEl);
    var px = (parseFloat(st.paddingLeft) || 0) + (parseFloat(st.paddingRight) || 0);
    var py = (parseFloat(st.paddingTop) || 0) + (parseFloat(st.paddingBottom) || 0);
    return { w: Math.max(80, containerEl.clientWidth - px), h: Math.max(80, containerEl.clientHeight - py) };
  }

  function configureFrame() {
    var s = innerSize(), m = 6;
    var scale = Math.min((s.w - 2 * m) / BASE_W, (s.h - 2 * m) / BASE_H);
    var halfW = (s.w - 2 * m) / (2 * scale), halfH = (s.h - 2 * m) / (2 * scale);
    dom = { x0: CX - halfW, x1: CX + halfW, y0: CY - halfH, y1: CY + halfH };
    setPlotFrame({ xDomain: [dom.x0, dom.x1], yDomain: [dom.y0, dom.y1], margin: m, draw: draw });
  }
  configureFrame();

  // ---- state ----------------------------------------------------------
  var F = null;                 // compiled outer boundary f(theta)
  var curTheta = 0.785;
  var view = 'Full region R';
  var thetaMax = Math.PI / 2;
  var areaR = 0;

  function fr(t) {
    if (!F) return NaN;
    var v;
    try { v = F(t); } catch (e) { return NaN; }
    return (typeof v === 'number' && isFinite(v)) ? v : NaN;
  }

  // ---- layers (z-order = creation order) ------------------------------
  var gAxes = draw.group();
  var gRegion = draw.group();

  var circleH = plotParametric('circle', {
    x: function (t) { return 2 * Math.cos(t); },
    y: function (t) { return 2 * Math.sin(t); },
    variables: ['t'], tDomain: [0, 2 * Math.PI], samples: 360,
    stroke: COL.circle, width: 3.5
  });
  var outerH = plotParametric('outer', {
    x: function (t) { var r = fr(t); return r * Math.cos(t); },
    y: function (t) { var r = fr(t); return r * Math.sin(t); },
    variables: ['theta'], tDomain: [0, 6.283185], samples: 520,
    stroke: COL.outer, width: 3.5
  });

  var gRay = draw.group();
  var gLab = draw.group();

  function setW(group, w) {
    group.each(function () {
      if (this.type === 'polyline' || this.type === 'polygon') this.stroke({ width: w });
    });
  }

  function hookup(el, tip, title, body) {
    el.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(tip, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup(title, body); });
  }

  // ---- geometry helpers ------------------------------------------------
  function computeThetaMax() {
    var g = function (t) { return fr(t) - 2; };
    var hi = Math.PI / 2, lo = 1e-4;
    if (!isFinite(g(lo)) || g(lo) <= 0) return 0;
    if (isFinite(g(hi)) && g(hi) > 0) return hi;
    var N = 300, prev = g(lo), pt = lo;
    for (var i = 1; i <= N; i++) {
      var t = lo + (hi - lo) * i / N, v = g(t);
      if (isFinite(prev) && isFinite(v) && prev > 0 && v <= 0) {
        var r = findRoot(g, pt, t, 1e-10);
        return (r == null) ? t : r;
      }
      prev = v; pt = t;
    }
    return hi;
  }

  function recompute() {
    thetaMax = computeThetaMax();
    if (thetaMax > 1e-4) {
      areaR = integrateSimpson(function (t) {
        var r = fr(t); if (!isFinite(r) || r < 2) r = 2;
        return 0.5 * (r * r - 4);
      }, 0, thetaMax, 240);
    } else areaR = 0;
  }

  function regionPoints(thEnd) {
    if (!(thEnd > 1e-4)) return null;
    var pts = [], n = 160, i, th, r;
    for (i = 0; i <= n; i++) {
      th = thEnd * i / n; r = fr(th);
      if (!isFinite(r) || r < 2) r = 2;
      pts.push([plotX(r * Math.cos(th)), plotY(r * Math.sin(th))]);
    }
    for (i = n; i >= 0; i--) {
      th = thEnd * i / n;
      pts.push([plotX(2 * Math.cos(th)), plotY(2 * Math.sin(th))]);
    }
    return pts;
  }

  function ptsAttr(p) { return p.map(function (q) { return q[0] + ',' + q[1]; }).join(' '); }

  // ---- drawing ---------------------------------------------------------
  function txt(g, wx, wy, s, fs, color, anchor, italic) {
    var t = g.text(s);
    t.font({
      family: 'Georgia, "Times New Roman", serif', size: fs,
      anchor: anchor || 'start', style: (italic === false ? 'normal' : 'italic')
    });
    t.fill(color || '#111');
    t.attr({
      'dominant-baseline': 'middle', 'paint-order': 'stroke',
      'stroke': '#ffffff', 'stroke-width': Math.max(2, fs * 0.32), 'stroke-linejoin': 'round'
    });
    var px = plotX(wx), py = plotY(wy);
    if (typeof t.amove === 'function') t.amove(px, py); else t.attr({ x: px, y: py });
    return t;
  }

  function drawAxes(UF) {
    gAxes.clear();
    var w = Math.max(1, 0.021 * UF);
    gAxes.line(plotX(dom.x0), plotY(0), plotX(dom.x1), plotY(0)).stroke({ color: COL.axis, width: w });
    gAxes.line(plotX(0), plotY(dom.y0), plotX(0), plotY(dom.y1)).stroke({ color: COL.axis, width: w });
    gAxes.circle(Math.max(3, 0.05 * UF)).center(plotX(0), plotY(0)).fill(COL.axis);
  }

  function drawRegion() {
    gRegion.clear();
    var end = 0;
    if (view === 'Full region R') end = thetaMax;
    else if (view === 'Swept region') end = Math.min(curTheta, thetaMax);
    else end = 0;
    if (end > 1e-4) {
      var pts = regionPoints(end);
      if (pts) {
        var poly = gRegion.polygon(ptsAttr(pts)).fill({ color: COL.fill, opacity: 0.95 }).stroke('none');
        hookup(poly,
          'Region R: outside r = 2, inside r = f(θ)',
          'The region R',
          'R is swept out by radial strips. For each θ between 0 and ' + thetaMax.toFixed(3) +
          ' the ray enters R at the inner curve r = 2 and leaves at the outer curve r = f(θ). ' +
          'Its area ∫∫ r dr dθ = ' + areaR.toFixed(3) + '.');
      }
    }
  }

  function drawStripWedge(UF) {
    var d = 0.07, n = 12, pts = [], i, th, r;
    var a = curTheta, b = Math.min(curTheta + d, Math.PI / 2 + d);
    for (i = 0; i <= n; i++) {
      th = a + (b - a) * i / n; r = fr(th);
      if (!isFinite(r) || r < 2) r = 2;
      pts.push([plotX(r * Math.cos(th)), plotY(r * Math.sin(th))]);
    }
    for (i = n; i >= 0; i--) {
      th = a + (b - a) * i / n;
      pts.push([plotX(2 * Math.cos(th)), plotY(2 * Math.sin(th))]);
    }
    gRay.polygon(ptsAttr(pts)).fill({ color: COL.strip, opacity: 0.85 }).stroke('none');
  }

  function drawRay(UF) {
    gRay.clear();
    var th = curTheta, ro = fr(th);
    if (!isFinite(ro)) ro = 2;
    if (view === 'Single strip') drawStripWedge(UF);

    var rEnd = Math.max(2, ro);
    var c = Math.cos(th), s = Math.sin(th);
    var thin = Math.max(1, 0.017 * UF), thick = Math.max(2, 0.05 * UF);

    gRay.line(plotX(0), plotY(0), plotX(rEnd * c), plotY(rEnd * s))
      .stroke({ color: COL.ray, width: thin, linecap: 'round' });

    if (ro > 2.0005) {
      var seg = gRay.line(plotX(2 * c), plotY(2 * s), plotX(ro * c), plotY(ro * s))
        .stroke({ color: COL.ray, width: thick, linecap: 'round' });
      hookup(seg,
        'strip: r goes from 2 to ' + ro.toFixed(2),
        'The inner (r) limits',
        'At this fixed θ = ' + th.toFixed(2) + ' the ray enters R at the circle r = 2 and exits at the outer curve r = ' +
        ro.toFixed(2) + '. Those two numbers are exactly the limits of the inner integral ∫ from r = 2 to r = f(θ).');
    }

    var dr = Math.max(3, 0.055 * UF);
    gRay.circle(dr).center(plotX(2 * c), plotY(2 * s)).fill('#ffffff').stroke({ color: COL.circle, width: Math.max(1, 0.02 * UF) });
    gRay.circle(dr).center(plotX(rEnd * c), plotY(rEnd * s)).fill('#ffffff').stroke({ color: COL.outer, width: Math.max(1, 0.02 * UF) });
  }

  function legendRow(g, y, fs, kind, color, text) {
    var x = dom.x0 + 0.12;
    if (kind === 'line') {
      g.line(plotX(x), plotY(y), plotX(x + 0.42), plotY(y)).stroke({ color: color, width: Math.max(2, fs * 0.22), linecap: 'round' });
    } else {
      var h = 0.24;
      g.rect(plotX(x + 0.42) - plotX(x), plotY(0) - plotY(h))
        .move(plotX(x), plotY(y + h / 2)).fill(color).stroke({ color: '#9ec6da', width: 0.8 });
    }
    txt(g, x + 0.58, y, text, fs, '#333', 'start', false);
  }

  function drawLabels(fs, UF) {
    gLab.clear();
    txt(gLab, -3.85, 1.6, 'r = 2', fs, '#111', 'start');
    txt(gLab, 1.15, 3.2, 'r = 2(1 + cos θ)', fs, '#111', 'start').text(outerLabelText());
    txt(gLab, -0.22, 2.9, 'θ = π/2', fs, '#111', 'end');
    txt(gLab, 1.55, -0.52, 'θ = 0', fs, '#111', 'start');

    var lf = fs * 0.72;
    legendRow(gLab, dom.y0 + 1.02, lf, 'line', COL.circle, 'inner boundary  r = 2');
    legendRow(gLab, dom.y0 + 0.62, lf, 'line', COL.outer, 'outer boundary  r = f(θ)');
    legendRow(gLab, dom.y0 + 0.22, lf, 'rect', COL.fill, 'region R');

    var ro = fr(curTheta);
    var lo = 2, hi = (isFinite(ro) && ro > 2) ? ro : 2;
    var l1 = 'θ = ' + curTheta.toFixed(2) + ',  r from ' + lo.toFixed(2) + ' to ' + hi.toFixed(2);
    var l2 = 'θ: 0 → ' + thetaMax.toFixed(2) + ',   area(R) = ' + areaR.toFixed(3);
    txt(gLab, dom.x1 - 0.12, dom.y0 + 0.62, l1, fs * 0.74, '#b02b23', 'end', false);
    txt(gLab, dom.x1 - 0.12, dom.y0 + 0.22, l2, fs * 0.74, '#333', 'end', false);

    var ro2 = document.getElementById('limitReadout');
    if (ro2) {
      ro2.innerHTML = 'θ = ' + curTheta.toFixed(2) + ' &nbsp; r: ' + lo.toFixed(2) + ' → ' + hi.toFixed(2) +
        '<br>∫<sub>0</sub><sup>' + thetaMax.toFixed(2) + '</sup> ∫<sub>2</sub><sup>f(θ)</sup> r dr dθ = ' + areaR.toFixed(3);
    }
  }

  var outerSrc = '2*(1+cos(theta))';
  function outerLabelText() {
    if (outerSrc.replace(/\s/g, '') === '2*(1+cos(theta))') return 'r = 2(1 + cos θ)';
    return 'r = ' + outerSrc.replace(/theta/g, 'θ').replace(/\*/g, '');
  }

  function redraw() {
    var UF = plotX(1) - plotX(0);
    var lw = Math.max(1.6, 0.045 * UF);
    setW(circleH.node, lw); setW(outerH.node, lw);
    drawAxes(UF);
    drawRegion();
    drawRay(UF);
    drawLabels(Math.max(8, Math.min(27, 0.215 * UF)), UF);
  }

  hookup(circleH.node, 'inner boundary  r = 2', 'Inner boundary r = 2',
    'The blue circle of radius 2 centred at the pole. Inside the first quadrant it is the curve where each radial ray ENTERS the region, so it supplies the lower limit r = 2 of the inner integral.');
  hookup(outerH.node, 'outer boundary  r = f(θ)', 'Outer boundary r = f(θ)',
    'The purple curve r = 2(1 + cos θ) is a cardioid with its cusp at the pole and its farthest point r = 4 at θ = 0. Each radial ray LEAVES the region here, so it supplies the upper limit r = f(θ).');

  // ---- controls --------------------------------------------------------
  window.update_thetaSweep = function (v) { curTheta = v; redraw(); };
  window.toggle_viewMode = function (v) { view = v; redraw(); };
  window.setOuter = function (src) {
    var inp = document.getElementById('fThetaInput');
    inp.value = src;
    inp.dispatchEvent(new Event('input'));
  };

  bindEquationInput('fThetaInput', function (fn, src) {
    F = fn; outerSrc = src;
    outerH.sample();
    recompute();
    redraw();
  }, { variables: ['theta'] });

  // ---- demo steps ------------------------------------------------------
  var steps = [
    {
      t: 'The two boundary curves',
      n: 'The blue circle r = 2 and the purple cardioid r = 2(1 + cos θ) both pass through (0, 2), and the cardioid reaches out to r = 4 at θ = 0. In the first quadrant the cardioid lies outside the circle.',
      s: { viewMode: 'Full region R', thetaSweep: 0.785 }
    },
    {
      t: 'One radial strip',
      n: 'Fix θ and follow the red ray outward: it enters R where r = 2 and leaves where r = 2(1 + cos θ). These are exactly the inner limits of integration.',
      s: { viewMode: 'Single strip', thetaSweep: 0.785 }
    },
    {
      t: 'The strip shrinks toward θ = π/2',
      n: 'As θ increases the cardioid pulls in toward the circle, so the strip gets shorter and vanishes at θ = π/2, where both curves meet at r = 2.',
      s: { viewMode: 'Single strip', thetaSweep: 1.5 }
    },
    {
      t: 'Sweeping θ builds the region',
      n: 'Sweep θ from 0 to π/2 and the strips accumulate into the shaded region R — the geometric meaning of the outer θ-limits.',
      s: { viewMode: 'Swept region', thetaSweep: 1.5708 }
    },
    {
      t: 'Change the outer curve',
      n: 'Edit the outer boundary formula and watch the intersection angle and the region change: the limits of integration are read directly off the curves, not memorized.',
      s: { viewMode: 'Full region R', thetaSweep: 0.785 }
    }
  ];
  var stepIdx = 0;

  function applyStep(i) {
    stepIdx = Math.max(0, Math.min(steps.length - 1, i));
    var st = steps[stepIdx].s;
    var sel = document.getElementById('viewModeInput');
    if (st.viewMode) { sel.value = st.viewMode; view = st.viewMode; }
    if (st.thetaSweep != null) {
      var sl = document.getElementById('thetaSweepInput');
      sl.value = st.thetaSweep;
      document.getElementById('thetaSweepVal').value = (+st.thetaSweep).toFixed(2);
      curTheta = +st.thetaSweep;
    }
    document.getElementById('demoNarration').innerHTML =
      '<b>' + steps[stepIdx].t + '</b><br>' + steps[stepIdx].n;
    document.getElementById('stepLabel').textContent = 'step ' + (stepIdx + 1) + ' / ' + steps.length;
    redraw();
  }
  window.nextStep = function () { applyStep(stepIdx + 1); };
  window.prevStep = function () { applyStep(stepIdx - 1); };

  // ---- resize ----------------------------------------------------------
  document.addEventListener('fig-resize', function () {
    configureFrame();
    circleH.sample();
    outerH.sample();
    redraw();
  });

  recompute();
  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

